steps.command:
branch="$(git branch --show-current)" || { printf '%s\n' 'ERROR: unable to determine current worktree branch with git branch --show-current.' >&2; exit 1; }; [ -n "$branch" ] || { printf '%s\n' 'ERROR: current worktree is detached; cannot review without a branch.' >&2; exit 1; }; results_file="${TMPDIR:-/tmp}/shh-cycle-review-$$.jsonl"; cleanup() { rm -f "$results_file"; }; trap cleanup 0 HUP INT TERM; : >"$results_file" || { printf '%s\n' 'ERROR: cannot create temporary review results file.' >&2; exit 1; }; "$REVIEW_SCRIPT" --branch "$branch" --results-file "$results_file" --device-udid "$REVIEW_DEVICE_UDID" --development-team "$DEVELOPMENT_TEAM"; review_status=$?; python3 - "$results_file" "$review_status" <<'PY'
import json
import sys

results_file = sys.argv[1]
review_status = int(sys.argv[2])
rows = []
errors = []
try:
    with open(results_file, encoding="utf-8") as handle:
        rows = [line.rstrip("\n") for line in handle if line.strip()]
except OSError as error:
    errors.append(f"unable to read results file: {error}")

if review_status != 0:
    errors.append(f"review script exited with status {review_status}")
if not rows:
    errors.append("review script recorded no result")

for line_number, row in enumerate(rows, 1):
    try:
        result = json.loads(row).get("result")
    except (TypeError, AttributeError, json.JSONDecodeError) as error:
        errors.append(f"invalid JSONL row {line_number}: {error}")
        continue
    if result != "good":
        errors.append(f"review result on row {line_number} is {result!r}, expected 'good'")

if errors:
    print("ERROR: review outcome rejected: " + "; ".join(errors), file=sys.stderr)
    print("Review JSONL rows:", file=sys.stderr)
    for row in rows:
        print(row, file=sys.stderr)
    sys.exit(1)
PY
